static void hexs(char *b, uint32_t v)
{
    uint32_t i;
    for (i = 0; i < 8u; i++)
        b[i] = "0123456789ABCDEF"[(v >> (28u - 4u * i)) & 15u];
    b[8] = 0;
}

/* the MIDI note (ch, src) of track id - 1 that plays a chord, 0 = none */
static mchord_t *mchord_of(uint32_t ch, uint32_t src, uint32_t id)
{
    uint32_t i;
    for (i = 0; i < MCHORD_N; i++)
        if (mchord[i].id == id && mchord[i].ch == ch && mchord[i].src == src)
            return &mchord[i];
    return 0;
}

/* bits i0 .. i1-1 of w (msb first) into the 595; the outputs stay as they are until fm1__sr_latch */
static void fm1__sr_bits(uint32_t w, uint32_t i0, uint32_t i1)
{
    uint32_t i;
    /* read-modify-write per edge on purpose: write-only edges were too short for the
     * 595 on the board and latched the neighbouring column (LEDs and keys copied one column over) */
    for (i = i0; i < i1; i++) {
        if (w & (0x8000u >> i))
            FM1_PR(FM1_PA, FM1_OUT) |= 1u << 4;
        else
            FM1_PR(FM1_PA, FM1_OUT) &= ~(1u << 4);
        FM1_PR(FM1_PA, FM1_OUT) |= 1u << 3;
        FM1_PR(FM1_PA, FM1_OUT) &= ~(1u << 3);
    }
}

/* Start with the last imported/saved object, including fields owned by a
 * feature absent from this build. No save-on-boot or extra flash writes. (2.0) An SKS1 */
static void settings_export(sks_t *s)
{
    s->magic = SKS_MAGIC;
    s->palette = palette_to_stored(settings.palette);
    s->lowcut = settings.lowcut;
    s->zoom = settings.zoom = leds_to_stored(settings.zoom, settings_leds);
    s->panel = panel;
    s->bold = hold_to_stored(s->bold, settings_hold);
    sks_pack(s, (const uint8_t (*)[32])favorites.factory, favorites.user, favorites.filter);
}

/* an imported older format may hold values FUN7 cannot pack: keep them inside the fields and ranges */
static void proj_bound(project_t *q)
{
    uint32_t t, i;
    for (t = 0; t < NTRK; t++) {
#if FELUCCA_LEGACY
        proj_steps(q->t[t].step);
        for (i = 0; i < NSTEP; i++) {
            step_t *s = &q->t[t].step[i];
            s->flags &= 3u | SF_RATCH | SF_FLAM;        /* ((Skiff) FLAM with x1 only, as proj_unpack reads it) */
            if (step_ratchet(s) > 1u) s->flags &= (uint8_t)~SF_FLAM;
            s->vel &= 127u;
            if (s->probability > 101u) s->probability = 0;
            if (s->cond >= TC_COUNT) s->cond = TC_NONE;  /* (Skiff) */
            if (s->nudge < NUDGE_MIN || s->nudge > NUDGE_MAX) s->nudge = 0;
        }
#endif
        for (i = 0; i < P_COUNT; i++) {
            const param_desc_t *d = param_desc_of(q->t[t].engine % NENGINES, i);
            q->t[t].p[i] = (int16_t)param_fit(d, q->t[t].p[i]);   /* (a retired KIT: the kit it plays) */
        }
    }
    q->sum = proj_sum(q);
}

static int bk_newer(uint32_t a, uint32_t b) { return a != b && a - b < 0x80000000u; }   /* (wraps) */
static void bk_lens(uint32_t c)                    /* chunk c's patterns (in bk_buf): their LENs for the page */
{
    uint32_t r;
    for (r = 0; r < BK_PER; r++) {
        const uint8_t *p = bk_buf + r * BK_REC;
        int32_t len = (int32_t)p[2] - 64;
        bk.len[c % BK_CHUNKS * BK_PER + r] = (uint8_t)(!bk_ver(p[0]) ? 0 : len < 1 ? 1 : len > (int32_t)NSTEP ? NSTEP : len);
    }
}

/* MENU > USB SERIAL (#67). The serial console is a developer tool (README: FELUCCA_CDC). ON (the default) presents it,
 * the descriptors byte for byte as before; OFF re-enumerates as audio + MIDI only, device class 0 (the bytes of a
 * FELUCCA_CDC=0 build): macOS 13-15 then attach their USB audio driver (with the console Apple's CDC composite driver
 * takes the device and the audio input never appears). USB-MIDI stays, and with it the editor, the update installer
 * and the soft key (SysEx on EP1). Applied at boot before USB starts (main.c: enumerated with it from the start, never
 * on then off) and while the menu is closed (ui_input: one re-enumeration when it closes, not one per KNOB 1 step).
 * A change from the editor (MENU_SET) waits 200 ms (menu_serial_at) so its reply leaves before the device drops off
 * the bus: the whole device re-enumerates, USB-MIDI and audio too */
static uint32_t menu_serial_at;                        /* fm1_ms | 1 of the editor's change; 0 none */
static void usb_serial_apply(void)
{
#if FELUCCA_CDC
    if (menu_serial_at && fm1_ms - menu_serial_at < 200u)
        return;
    menu_serial_at = 0;
    usb_cdc_switch(FELUCCA_CDC_DEFAULT && !(ui_prefs & PREF_SERIAL_OFF));   /* (a FELUCCA_CDC_DEFAULT=0 build: off) */
#endif
}

/* the torch: the flame (two frames, flickering), its head, the stick; 5 x 12, z times that (2 and more: in a 1 px dark
 * outline, so it shows on a band of its own amber: HOME's selected track) */
static void cr_torch(int32_t x, int32_t y, uint32_t frame, int32_t z)
{
    const uint8_t *T = frame & 1u ? SPR_TORCH1 : SPR_TORCH0;
    const uint16_t cols[5] = {CR_GOLD, CR_FLAME, T_THEME, CR_EMBER, T_DIM};
    uint32_t j, i;
    for (j = 0; z > 1 && j < 12u; j++)
        for (i = 0; i < 5u; i++)
            if (spr_px(T, j * 5u + i))
                cv_rect(x + (int32_t)i * z - 1, y + (int32_t)j * z - 1, z + 2, z + 2, T_BG);
    ui_sprite(x, y, T, 5u, cols, z);
}

/* a charged particle's track from (x, y), heading `dir` (a turn 2^32), curling one way (curl +-1) ever tighter as it
 * slows, `len` px, its first n drawn ((Skiff Q6) n < len: still flying out); its colour fading into `under`;
 * -> where it has got to, x << 16 | y */
static uint32_t qk_track(int32_t x, int32_t y, uint32_t dir, int32_t r, int32_t len, int32_t curl, uint16_t c,
                         uint16_t under, int32_t n)
{
    int32_t dx = QK_COS(dir) / 8, dy = QK_SIN(dir) / 8, fx = x << 12, fy = y << 12, k;   /* (Q12) */
    for (k = 0; k < n; k++) {
        int32_t rr = r - r * 6 * k / (10 * len), t = 4096 / (rr > 4 ? rr : 4) * curl, ndx = dx - dy * t / 4096;
        dy += dx * t / 4096;
        dx = ndx;
        fx += dx;
        fy += dy;
        cv_rect(fx >> 12, fy >> 12, 1, 1, ux_mix(c, under, 65 * k / len));
    }
    return (uint32_t)(fx >> 12) << 16 | ((uint32_t)(fy >> 12) & 0xFFFFu);
}

/* ---------------------------------------------------- the track's patch --- */
/* track tr's patch = v (155 bytes, sanitized). Main loop: the ISR takes it at its next block */
static void fm6_set_patch(uint32_t tr, const uint8_t *v)
{
    uint8_t s[FP_SIZE + 1u];
    tr %= NTRK;
    memcpy(s, v, FP_SIZE);
    fm6_sanitize(s);                                /* not in place: fm6_sync must never copy an unsanitized byte */
    memcpy(fm6_patch[tr], s, FP_SIZE + 1u);
    RING_PUBLISH();
    fm6_pgen[tr]++;
}

/* power-on: every track the init voice (what a project stores for the tracks that never played FM6) */
static void fm6_init(void)
{
    uint8_t v[FP_SIZE + 1u];
    uint32_t tr;
    fm6_unpack(FM6_INIT, v);
    for (tr = 0; tr < NTRK; tr++) {
        fm6_set_patch(tr, v);
        fm6_slot[tr] = 0xFFu;
    }
}

static void track_defaults(track_t *t)
{
    uint32_t i;
    for (i = 0; i < P_E0; i++)
        t->p[i] = TP[i].def;
    track_defaults_steps(t);
}

/* the ink box of icon id drawn at (0, 0) in a size px cell: b = x0 y0 x1 y1 (past the ink), from the generator's
 * table (tools/gen_aa_icons.py AI*_INK); a cushion: the cushion; nothing: the cell */
static void icon_ink(uint32_t size, uint32_t id, int32_t *b)
{
    uint32_t sz = size, v, i;
    int32_t k = id - ICON_TRK < NTRK ? -1 : icon_cell(&sz, id), in = id - ICON_TRK < NTRK && size > 16u ? 2 : 0;
    if (id - ICON_TRK < NTRK && trk_bare(size)) {   /* (Skiff) BLOCKS: the bare figure (cv_trk): across its ink, */
        char s[2] = {(char)('1' + (id - ICON_TRK)), 0};   /* up and down the capitals' band */
        text_ink(trk_face(size), s, b);
        b[1] = TRK_TOP(size);
        b[3] = b[1] + TRK_CAP_H(size);
        return;
    }
    if (k < 0) {
        b[0] = b[1] = in;
        b[2] = b[3] = (int32_t)size - in;
        return;
    }
    if (sz == 24u) {
        v = AI24_INK[k];                            /* x0 y0 x1 y1: a byte each */
    } else {                                        /* 12 16: a nibble each, x1-1 y1-1: as the 24's */
        v = sz == 16u ? AI16_INK[k] : AI12_INK[k];
        v = ((v & 15u) | (v & 0xF0u) << 4 | (v & 0xF00u) << 8 | (v & 0xF000u) << 12) + 0x01010000u;
    }
    for (i = 0; i < 4u; i++)
        b[i] = (int32_t)(v >> (8u * i) & 255u);
}

/* pattern id, read and checked, for track t: its steps, LEN DIV SWING GATE DIR (fitted to t's sound), its automation
 * and locks (t's places): 0 ok, 1 nothing there (or a record no firmware wrote) */
static int pat_decode(const track_t *t, uint32_t id, step_t *st, int16_t *v, motion_store_t *ms)
{
    uint8_t *r = bk_buf;
    uint32_t tk = trk_index(t), i, out;
    bk_bufc = 0;
    if (pat_read(id, r))                           /* (a waiting copy first) */
        return 1;
    memset(st, 0, NSTEP * sizeof *st);
    for (i = 0; i < NSTEP; i++)
        if (!step_get9(&st[i], r + BK_STEPS + i * 9u))
            return 1;
    nudge_unpack(st, r + BK_NUDGE, NSTEP);
    for (i = 0; i < 5u; i++)
        v[i] = (int16_t)param_fit(track_desc(t, BK_TIME[i]), (int32_t)r[2u + i] - 64);
    memset(ms, 0, sizeof *ms);
    ms->count = (uint8_t)(r[7] & 127u);
    ms->on = (uint8_t)(r[7] & 128u ? 1u << tk : 0u);
    for (i = out = 0; i < ms->count && i < MOTION_MAX; i++) {
        const uint8_t *m = r + BK_MOT + i * 4u;
        int32_t val = (int16_t)(m[2] | (uint16_t)m[3] << 8);   /* (stored 16 bits: checked before it is a byte) */
        ms->event[i].place = (uint16_t)(tk << 6 | (m[0] & 63u));
        ms->event[i].id = (uint8_t)((m[1] & 127u) | (m[0] & 64u) << 1);   /* ((1.3) bit 7: BK_VER2's; 0 before) */
        ms->event[i].lock = m[1] >> 7;
        ms->event[i].value = (int8_t)val;
        out |= val < -64 || val > 127;
    }
    if (out || !proj_motion_ids(ms, r[1]) || !motion_valid(ms))
        ms->count = 0;                             /* (motion no firmware wrote: the steps still load) */
    return 0;
}

static int16_t motion_base_value(const track_t *t, uint32_t id)
{
    uint32_t k = trk_index(t);
    return (motion_active[k][id / 32u] >> (id % 32u)) & 1u ? motion_base[k][id] : t->p[id];
}

/* a pattern -> record r: steps st, LEN DIV SWING GATE DIR tv (the sound's own), the events of ms placed on track k, the
 * automation on or not: 0 for a step no format can hold (none the UI makes) */
static int bk_pack_raw(uint8_t *r, uint32_t k, const step_t *st, const int16_t *tv, const motion_store_t *ms, int on)
{
    uint32_t i, n = 0, np = PROJ_NP, ties = 0;
    /* ((Skiff phase 9) the motion's ids as a store of PROJ_NP has them, which firmware before reads; today's when it
     * names a parameter added since) */
    for (i = 0; i < ms->count && i < MOTION_MAX; i++)
        if ((ms->event[i].place >> 6) == k && MOTION_ID(&ms->event[i]) >= PROJ_NP - 8u && MOTION_ID(&ms->event[i]) < P_E0)
            np = P_COUNT;
    memset(r, 0, BK_REC);
    r[0] = BK_VER;
    r[1] = (uint8_t)np;
    for (i = 0; i < 5u; i++)
        r[2u + i] = (uint8_t)(tv[i] + 64);
    for (i = 0; i < NSTEP; i++) {
        if (!step_put9(r + BK_STEPS + i * 9u, &st[i]))
            return 0;
        ties |= step_ties(&st[i]);
    }
    nudge_pack(r + BK_NUDGE, st, NSTEP);
    for (i = 0; i < ms->count && n < MOTION_MAX; i++) {
        const motion_event_t *e = &ms->event[i];
        uint8_t *m = r + BK_MOT + n * 4u;
        if ((e->place >> 6) != k)
            continue;
        uint32_t id = np == P_COUNT || MOTION_ID(e) < P_E0 ? MOTION_ID(e) : MOTION_ID(e) - PROJ_ESHIFT;
        m[0] = (uint8_t)((e->place & 63u) | (id >> 7) << 6);   /* ((1.3) the id's bit 7: BK_VER2) */
        m[1] = (uint8_t)((id & 127u) | (e->lock ? MOTION_LOCK : 0u));
        if (id > 127u)
            r[0] = BK_VER2;
        m[2] = (uint8_t)e->value;
        m[3] = (uint8_t)((uint16_t)e->value >> 8);
        n++;
    }
    r[7] = (uint8_t)(n | (on ? 128u : 0u));
    if (ties)
        r[0] = BK_VER3;                            /* ((2.0) its ids as BK_VER2's too) */
    return 1;
}

static int project_restore_runtime(const project_t *input)
{
    project_t *p = &proj_scratch;
    uint32_t i, k;
    if (!proj_ok(input) || !proj_engines_ok(input)) return 1;
    if (p != input) memcpy(p, input, sizeof *p);
#if FELUCCA_LEGACY
    proj_drums_to_part(p);                              /* a RAM slot of firmware before 1.0 */
    proj_phys(p);                                       /* .. before PHYS lost DUST and DRUM */
    proj_fm4(p);                                        /* .. that had DIGITAL tracks */
    proj_perc(p);                                       /* .. or SAMPLE PERC tracks */
#endif
    transport_req = 2;
    panic_req = (1u << NTRK) - 1u;
    fm1_irq_off();                                      /* the audio ISR must not see half a project */
    seq_stop();
    launch_drop();                                      /* (Skiff) the bank's staged patterns: not over it (launch.c) */
    transport_req = 0;
#if FELUCCA_LEGACY
    motion = p->motion;
#else
    memset(&motion, 0, sizeof motion);                  /* ((2.0) the patterns hold it: each track's, as it loads) */
#endif
    memset(motion_active, 0, sizeof motion_active);
    motion_base_valid = 0;
    memcpy(lists.ent, p->ent, sizeof lists.ent);       /* (phase 5) the lists; the tracks on no pattern yet */
    memcpy(lists.snd, p->snd, sizeof lists.snd);       /* ((2.0, #30) the entries' sounds) */
    memcpy(lists.cur, p->cur, sizeof lists.cur);
    lists.song = p->song;
    memcpy(lists.scene, p->scene, sizeof lists.scene);
    scene_forget();
    memset(trk_pid, 0, sizeof trk_pid);
    motion_lost = 0;
    for (i = 0; i < G_COUNT; i++)                       /* ((Skiff U3, R8) not the unit's CLOCK MIDI IN TUNE: ui.c) */
        if (i != G_SLOT && i != G_LOAD && i != G_SAVE && (unit_g_adopt || !unit_g_id(i)))
            song.g[i] = (int16_t)clamp(p->g[i], GP[i].min, GP[i].max);
    for (k = 0; k < NTRK; k++) {
        track_t *t = &trk[k];
        const proj_trk_t *s = &p->t[k];
        uint32_t e = s->engine;                         /* (< NENGINES: proj_engines_ok) */
        t->eng_req = (uint8_t)e;
        t->user = s->user && up_used(s->user - 1u) && up_engine(s->user - 1u) == e ? s->user : 0u;   /* ((2.0, #20)
                                                         * the user sound it came from, while that slot still holds one
                                                         * of its engine: HOME and EDIT name it; else none, as before) */
        for (i = 0; i < P_COUNT; i++) {                 /* every value back inside its range (param_fit) */
            const param_desc_t *d = param_desc_of(e, i);
            t->p[i] = (int16_t)param_fit(d, s->p[i]);
        }
        t->preset = (uint8_t)(ENGINES[e]->npresets ? (s->preset >= PROJ_DEF_KEEP ? 0u : s->preset) % ENGINES[e]->npresets : 0u);
#if FELUCCA_LEGACY
        memcpy(t->step, s->step, sizeof t->step);
        proj_steps(t->step);
#else
        memset(t->step, 0, sizeof t->step);             /* ((2.0) none until its pattern loads, below) */
        for (i = 0; i < NSTEP; i++)
            t->step[i].time = ST_REST;
#endif
        {   /* the project's own FM6 patch, never reloaded from SLOT: F n if it is that factory patch, else OWN */
            uint8_t v[FP_SIZE + 1u];
            fm6_unpack(p->fm6[k], v);
            fm6_set_patch(k, v);
            fm6_adopt(k);
        }
    }
    sel_set((uint8_t)(p->sel < NTRK ? p->sel : 0u));
    memcpy(dx_kit, p->dx_on && dx_kit_ok(p->dx) ? p->dx : DX_KIT_DEF, sizeof dx_kit);   /* (phase 7) its DRUM-X kit */
    fm1_irq_on();
    proj_name_get(proj_name, (const uint8_t *)p->name);
    proj_cur = PROJ_NO_SLOT;                            /* (project_load: its slot) */
    undo_clear();                                       /* (ui.c) the undo copies belong to the old project */
    undo_depth++;                                       /* and these loads take none */
    for (k = 0; k < NTRK; k++) {                        /* the power-on sounds: format 1 (tracks 2..4), old drums */
        track_t *t = &trk[k];
        if (p->t[k].preset == PROJ_DEF_SOUND) {
            apply_preset_to(t, TRK_DEF[k][1]);
            track_defaults_steps(t);
        }
#if FELUCCA_LEGACY
        else if (p->t[k].preset == PROJ_DEF_KEEP) {     /* the steps, LEVEL PAN MUTE, LEN DIV SWING GATE kept */
            int16_t keep[P_COUNT];
            memcpy(keep, t->p, sizeof keep);
            fm1_irq_off();                           /* publish the legacy sound as one bounded parameter batch */
            proj_legacy_drums(t);                     /* (keeps the SLICER: param_kept) */
            t->p[P_REV] = keep[P_REV];                  /* and the drums' reverb send */
            for (i = P_AMODE; i <= P_TRANS; i++)        /* the drum part had no arp or scale */
                t->p[i] = TP[i].def;
            fm1_irq_on();
        }
#endif
        {   /* (phase 5) the pattern of the entry it is on (SKF2); none: the record's steps (a format before) */
            uint32_t id = ent_pat(k, lists.cur[k]);
            if (id != PAT_NONE && pool_used(id))
                (void)pat_load(t, id);
        }
    }
    undo_depth--;
    sync_reload = 1;
    ui.force = 1;
    ui_message("LOADED");
    memset(snd_said, 0, sizeof snd_said);               /* a missing sample is said again, after LOADED */
    return 0;
}

static void ed_shadow(void)                              /* the editor is in sync */
{
    uint32_t i;
    for (i = 0; i < ED_NV; i++)
        ed_w.v[i] = *ed_val(i);
    for (i = 0; i < NSTEP; i++)
        ed_w.st[i] = ed_step_sig(&TSEL->step[i]);
    for (i = 0; i < ED_NT; i++)
        ed_w.tv[i] = trk[i / 3u].p[ED_TIDS[i % 3u]];
    ed_w.eng = (uint8_t)ed_eng(TSEL);
    ed_w.preset = TSEL->preset;
    ed_w.sel = song.sel;
    sync_reload = 0;
}

static void ed_bk_pack(const uint8_t *p, uint32_t n)   /* (editor_backup.c's) */
{
    while (n) {
        uint32_t k = n > 7u ? 7u : n, mask = 0, i;
        for (i = 0; i < k; i++) mask |= (uint32_t)(p[i] >> 7) << i;
        ed_b(mask);
        for (i = 0; i < k; i++) ed_b(p[i]);
        p += k; n -= k;
    }
}

static int up_pat(const up_rec_t *r) { return r->ver < UP_VER_SID; }   /* (it holds a 16-step pattern's fields) */
/* value k as stored: its place by count (versions 1..5) or (v6) its stored id */
static int16_t up_value(const up_rec_t *r, uint32_t k) { return r->ver >= 4u ? (int16_t)r->sid[k] - 64 : r->p[k]; }

/* a stored project renamed in place (nothing else of it changes; the music playing is not touched, but the slot
 * it was loaded from / saved to: its name is the new one, the next SAVE's prefill): 0 done, 1 refused (playing,
 * an empty slot), 2 failed (the slot as it was) */
static int project_rename(uint32_t slot, const char *name)
{
    project_t *p = &proj_scratch;
    const proj_fmt_t *f = proj_fmt_of(&proj_slot[slot & 3u], sizeof(project_store_t));   /* (phase 5, 6) its format
                                                                                * kept: SKF2 .. SKF4 name their patterns */
    if (transport_busy()) {
        ui_message("STOP TO SAVE");
        return 1;
    }
    if (!proj_import(p, &proj_slot[slot & 3u], sizeof(project_store_t))) {
        ui_message(proj_old(slot) ? "OLD FORMAT" : "EMPTY SLOT");
        return 1;
    }
    memset(p->name, 0, sizeof p->name);
    memcpy(p->name, name, str_len(name) < PROJ_NAME_LEN ? str_len(name) : PROJ_NAME_LEN);
    proj_wire_gen++;
#if FELUCCA_LEGACY
    if (!(f ? proj_pack2(&proj_wire, p, f) : proj_pack(&proj_wire, p))) { ui_message("SAVE FORMAT ERROR"); return 2; }
#else
    if (!proj_pack2(&proj_wire, p, f)) { ui_message("SAVE FORMAT ERROR"); return 2; }
#endif
#if FELUCCA_FLASH
    if (flash_ok && st_save(OBJ_PROJECT0 + (slot & 3u), &proj_wire, f ? f->size : sizeof proj_wire)) {
        ui_message("SAVE ERROR");
        return 2;
    }
#endif
    memcpy(&proj_slot[slot & 3u], &proj_wire, sizeof proj_wire);
    if (proj_cur == (slot & 3u)) {                      /* (the music's name too: as it was, saved or not) */
        int was = !project_changed();
        proj_name_get(proj_name, (const uint8_t *)p->name);
        if (was)
            project_clean();
    }
#if FELUCCA_FLASH
    if (flash_ok) { ui_message("RENAMED"); return 0; }
#endif
    ui_message("RENAMED UNTIL POWER OFF");
    return 0;
}

/* (2.0) record r emptied: no steps, NUDGEs or automation, the version every firmware reads; its LEN DIV SWING GATE DIR
 * kept, or track t's (NEW) */
static void rec_empty(uint8_t *r, const track_t *t)
{
    step_t e;
    uint32_t i;
    for (i = 0; t && i < 5u; i++)                  /* ((2.0.2) GATE the default, 1 STEP: the track's can be a 1.x
                                                    * pattern's 50 %) */
        r[2u + i] = (uint8_t)((BK_TIME[i] == P_SGATE ? TP[P_SGATE].def : motion_base_value(t, BK_TIME[i])) + 64);
    memset(&e, 0, sizeof e);
    step_clear(&e);
    (void)step_put9(r + BK_STEPS, &e);
    for (i = 1; i < NSTEP; i++)
        memcpy(r + BK_STEPS + i * 9u, r + BK_STEPS, 9u);
    memset(r + BK_NUDGE, 0, BK_REC - BK_NUDGE);
    r[0] = BK_VER;
    r[1] = PROJ_NP;
    r[7] = 0;
}

/* ---- (phase 5) the lists (ui.c lists): a track plays the pattern of the entry it is on, and what it has is kept as
 * that pattern (trk_pid); a new one gets the first free id when it is first kept. The (track, entry) functions keep
 * the bank's names: PERFORM's keys, SAVE > PATTERNS, the scenes ---- */
static uint32_t pool_len(uint32_t id)               /* pattern id's LEN, 0 empty (a waiting copy's first) */
{
    uint32_t i = pend_at(id);
    int32_t len;
    if (i == PEND_N)
        return bk.len[id % BK_POOL];
    if (!bk_ver(pend_rec[i][0]))
        return 0;
    len = (int32_t)pend_rec[i][2] - 64;
    return (uint32_t)(len < 1 ? 1 : len > (int32_t)NSTEP ? (int32_t)NSTEP : len);
}

/* descriptor and value slot of (scope, id): scope 0 / 2 = the selected track, 1 = global */
static const param_desc_t *ed_desc(uint32_t scope, uint32_t id, int16_t **vp)
{
    if (scope != 1u) {
        if (scope > 2u || (id = ED_TID(scope, id)) >= P_COUNT)
            return 0;
        *vp = &TSEL->p[id];
        return ed_tdesc(TSEL, id);
    }
    if (scope == 1 && id < G_COUNT) {
        *vp = &song.g[id];
        return &GP[id];
    }
    return 0;
}

static int str_eq(const char *a, const char *b)
{
    while (*a && *a == *b) {
        a++;
        b++;
    }
    return *a == *b;
}

static void run_undo(track_t *t, const char *name)
{
    if (!(undo_n && !undo_back && undo.name == name && undo.trk == trk_index(t) + 1u && track_sig(t) == undo.after &&
          fm1_ms - undo.t_ms < 1500u))
        tl_undo_take(t, name);
}

static void rec_set(uint32_t r, uint32_t v)
{
    if (v == rp_get(RL_F[r]))
        return;
    rp_put(RL_F[r], v);
    lys.rp_dirty = 1;
}

static uint32_t preset_at(uint32_t n, uint32_t *k)
{
    uint32_t all;
    if (!list_mode()) return preset_all_at(n, k);
    preset_all_pos(&all);
    for (uint32_t i = 0; i < all; i++) {
        uint32_t e = preset_all_at(i, k);
        if (preset_in_list(e, *k) && !n--) return e;
    }
    *k = UP_SLOTS;
    return NENGINES;
}

static void edit_param(uint32_t slot, int32_t steps)
{
    int16_t *vp;
    const page_t *pg = cur_page();
    const param_desc_t *d;
    int32_t v;
    if (pg->graph == GR_FEEL) {                           /* (Skiff 2.0) FEEL: CHANCE RATCHET NUDGE TYPE of the selection */
        follow_hold();                                    /* ((1.3) the edited steps stay on the screen) */
        feel_turn(TSEL, slot, steps);
        return;
    }
    if (pg->graph == GR_EVENTS) {                         /* AUTO LIST (ui_events.c) */
        ev_knob(slot, steps);
        return;
    }
    if (pg->graph == GR_SONG) {                           /* (Skiff phase 5) SONG */
        song_knob(slot, steps);
        return;
    }
    if (sheet_of(pg->graph)) {                            /* (Skiff phase 7, 8; FM6 LAB) a sheet: its window (SHEETS) */
        sheet_of(pg->graph)->knob(slot, steps);
        return;
    }
    if ((pg->graph == GR_LANES || pg->graph == GR_LMIX) && slot == 0u) {   /* (Skiff U3, R6) LANES: KNOB 1 the lane (the
                                                         * grid's too), KNOB 2 its level (params.c page_desc); ((2.0, #36)
                                                         * LANE MIX the same, DRUM-X's: the sound sheet's) */
        uint8_t *l = page_lane_p();
        *l = (uint8_t)clamp((int32_t)(*l % 8u) + steps, 0, 7);
        return;
    }
    if (pg->scope == SC_STEP) {
        step_edit(slot, steps);
        return;
    }
    if (pg->scope == SC_TRK) {
        tracks_edit(slot, steps);
        return;
    }
    if (pg->graph == GR_BROWSE) {                         /* KNOB 1: one preset, KNOB 2: the next / previous engine */
        if (slot == 0u) {
            preset_step(steps);
        } else if (slot == 1u) {
            select_engine(eng_step_for(song.sel, TSEL->eng_req, steps));   /* ((Skiff phase 6) what the track may play) */
        } else if (slot == 2u) {
            preset_mark(steps > 0);
        } else if (slot == 3u) {                          /* LIST: ALL, FAV, (Skiff phase 9) then the types (ui.c) */
            uint32_t v = (uint32_t)clamp((int32_t)list_mode() + steps, 0, PT_N);
            if (v != list_mode()) {
                favorites.filter = v == 1u;
                ui_ptag = (uint8_t)(v > 1u ? v - 1u : 0u);
                ui.force = 1;
                settings_later();                         /* (Felucca #197: not on every detent; ui.c) */
            }
        }
        return;
    }
#if FELUCCA_SLICE
    if (pg->graph == GR_SLICES && slot < 2u) {           /* SLICES: KNOB 1 the marker, 2 moves it (ui_slice.c) */
        if (slice_page_ok())                              /* (the engine changed before ui_draw left the page) */
            slice_knob(slot, steps);
        return;
    }
#endif
    if ((pg->graph == GR_USER && slot == 2u) || (pg->graph == GR_SLOTS && slot == 1u)) {   /* (Skiff U2) USER's KNOB 3:
                                                           * ERASE, one step further NAME; (1.2.1, #6) PROJECT's KNOB 2:
                                                           * DELETE, then NAME */
        int32_t st = ui.act == slot + 1u ? 1 + (int32_t)ui.act2 : 0;
        st = clamp(st + steps, 0, 2);
        ui.act = st ? (uint8_t)(slot + 1u) : ui.act == slot + 1u ? 0u : ui.act;
        ui.act2 = st == 2;
        return;
    }
    if (pg->graph == GR_BANK && slot == 3u) {             /* ((2.0, #46) PATTERNS' KNOB 4: the ACTION, OCT+ does it */
        ui.bact = (uint8_t)clamp((int32_t)ui.bact + (steps > 0 ? 1 : -1), 0, BA_N - 1);
        return;
    }
    if ((act_cols() >> slot) & 1u) {                      /* an action's knob picks it (right) or drops it (left); */
        ui.act = steps > 0 ? (uint8_t)(slot + 1u) : ui.act == slot + 1u ? 0u : ui.act;   /* OCT+ does it (act_do) */
        ui.act2 = 0;
        return;
    }
    if (pg->graph == GR_USER) {                           /* KNOB 1 the slot */
        if (slot == 0u)
            ui.uslot = (uint8_t)clamp((int32_t)ui.uslot + steps, 0, UP_SLOTS - 1);
        return;
    }
    if (pg->graph == GR_BANK) {                           /* (Skiff phase 5) PATTERNS: KNOB 1 the pattern, 01 .. 64 */
        if (slot == 0u)
            ui.bslot = (uint8_t)clamp((int32_t)ui.bslot + steps, 0, NPAT - 1);
        return;
    }
    if (pg->graph == GR_MOD && slot == 0u) {             /* MOD: KNOB 1 the route ((2.0) the fixed seven, then the slots), */
        mod_ui_route = (uint8_t)clamp((int32_t)mod_ui_route + (steps > 0 ? 1 : -1), 0, MOD_ROUTES - 1u);   /* 2..4 its */
        return;                                                                                            /* SRC DST AMT */
    }
    d = page_desc(pg, slot, &vp);
    if (!d || !vp || d->max == d->min)
        return;
    v = param_turn(d, *vp, accel(EN_K1 + slot, steps, d->fmt == F_ENUM ? 0 : d->max - d->min));
    if ((vp == &TSEL->p[P_DKSRC] || vp == &TSEL->p[P_FOLLOW]) && v == (int32_t)(song.sel % NTRK) + 1)
        v = v == d->max ? *vp : v + (steps > 0 ? 1 : -1);   /* (Skiff) DUCK BY, (2.1) FOLLOW: never the track itself */
    *vp = (int16_t)v;
    if (pg->scope != SC_GLOBAL) {
        motion_capture(TSEL, (uint32_t)(vp - TSEL->p), *vp);
        ml_knob(TSEL, (uint32_t)(vp - TSEL->p));        /* ((1.3) MIDI LEARN: picked) */
    }
}

/* live recording into the selected track now: the STEP page's key entry pauses meanwhile */
