static uint32_t project_mark(void)
{
    return proj_cur < 4u ? ('A' + proj_cur) | (uint32_t)project_dirty() << 8 : 0u;
}

/* "[OCT+]..." -> the keycap's id and the length of the bracket, else -1 (a bracketed word that is no keycap is text) */
static int32_t kc_tag(const char *s, uint32_t *len)
{
    uint32_t i, n;
    if (s[0] != '[')
        return -1;
    for (n = 1; s[n] && s[n] != ']'; n++)
        if (n > 8u)
            return -1;
    if (s[n] != ']')
        return -1;
    for (i = 0; i < KC_COUNT; i++) {
        const char *l = KC[i].label;
        uint32_t k = 0;
        while (k + 1u < n && l[k] == s[k + 1u])
            k++;
        if (k + 1u == n && !l[k]) {
            *len = n + 1u;
            return (int32_t)i;
        }
    }
    return -1;
}

/* one card = one knob: [icon] LABEL / value unit / gauge on a SURF card, redrawn only when it changed.
 * The value is M, or S when M is too wide (engine names, long ENUMs); the unit S after it. The gauge is
 * a 3 px rounded bar: BG track, THEME fill. The knob just turned (hot): icon, label, value and gauge in
 * the accent. ratio: 0..1000 for the gauge, -1 = no gauge. icon: ICON_* (icons.c), ICON_AUTO = by label;
 * a label too long to share the card with its icon goes without it. A parameter MOTION drives (card_mot_next):
 * the motion icon in place of its own, in the theme colour; a long label moves it left, up to the card's edge;
 * a label with no room for it at all (or FELUCCA_ICONS=0): the label in the theme colour.
 * vr: the value's colour, a VR_* role (ui.c: VR_LIVE the theme's, the accent while its knob is the one just turned) */
static void draw_column(uint32_t c, const char *label, const char *val, const char *unit, uint32_t vr,
                        int32_t ratio, uint32_t icon)
{
    char key[48];
    int hot = c == ui.hot_col && ui.hot_t, named = fmt_named, mot = card_mot_next && label[0], strip, snap;
    uint16_t vc = vr == VR_LIVE ? (hot ? T_ACCENT : T_THEME) : vr == VR_DIM ? T_DIM : vr == VR_ACCENT ? T_ACCENT
                : vr == VR_MID ? T_MID : T_THEME;
    uint32_t kind = large_kind();                       /* MENU > LARGE: tall (draw_column_tall), or the label in M */
    int blocks = kind != LK_TALL;                       /* Skiff: BLOCKS' tile (ui_blocks.c), its values snap; LARGE's
                                                         * tall card: the older one */
    uint8_t sig;
    uint16_t lc = hot ? T_ACCENT : T_MID;
    int32_t x, lx = 5, uw, room = COL_W - 8;
    const aafont_t *vf = &AF_M;
    uint32_t n, kn;
    int32_t kid = kc_tag(val, &kn);
    card_span_t sp = card_span;                         /* (Felucca #251: what the knob shows, this card only) */
    card_span.fn = 0;
    fmt_named = 0;                                      /* (params.c: a name, for this card only) */
    card_mot_next = 0;                                  /* (the same: MOTION, this card only) */
    card_mot = (uint8_t)((card_mot & ~(1u << c)) | (uint32_t)mot << c);
    if (str_eq(unit, label))
        unit = "";                                      /* "BPM 124 BPM", "USB OFF USB": the label says it */
    if (icon == ICON_AUTO)
        icon = icon_for_label(label);
    str_cpy(key, label, 12);                            /* cache key: texts + colour + gauge */
    str_cpy(key + str_len(key), "|", 2);
    str_cpy(key + str_len(key), val, 14);
    str_cpy(key + str_len(key), "|", 2);
    str_cpy(key + str_len(key), unit, 8);
    n = str_len(key);
    /* every RGB565 bit: status colours can change with identical text */
    key[n] = (char)('A' + (vc & 15u));
    key[n + 1] = (char)('A' + ((vc >> 4) & 15u));
    key[n + 2] = (char)('A' + ((vc >> 8) & 15u));
    key[n + 3] = (char)('A' + (vc >> 12));
    key[n + 4] = (char)('A' + (ratio < 0 ? 0 : 1 + ratio % 32));   /* ((Skiff) the gauge exactly: in 20ths its end moved */
    key[n + 5] = (char)('A' + (ratio < 0 ? 0 : ratio / 32));       /* a pixel under the same text, the card not redrawn) */
    key[n + 6] = (char)(icon == ICON_NONE ? '~' : '!' + icon % 90u);
    key[n + 7] = (char)('0' + hot + 2 * mot + 4 * (int)kind);
    key[n + 8] = 0;
    uw = unit[0] ? text_w(&AF_S, unit) + 3 : 0;
    if (text_w(vf, val) + uw > room)
        vf = &AF_S;
    sig = (uint8_t)str_hash(str_hash(song.sel + TSEL->eng_req * 4u + ux.gen * 64u, label), unit);
    snap = ui.force || sig != ui.roll[c].sig;           /* what the value is of: label, unit, track, engine, palette */
    if (kind == LK_TALL || blocks)
        ui.roll[c].from[0] = 0;                         /* (a tall card: no rolling digits) */
    strip = !snap && str_eq(key, ui.col[c]);
    if (strip && !ui.roll[c].from[0])
        return;
    if (strip) {                                        /* rolling: the value strip only */
        cv_begin(COL_W, ROLL_H, T_SURF);
        cv_oy = -ROLL_Y;
    } else {
        char ov[16];                                    /* the value drawn before (in the cache key) */
        const char *k = ui.col[c];
        uint32_t i = 0;
        while (*k && *k != '|')
            k++;
        while (*k && k[1] && k[1] != '|' && i + 1u < sizeof ov)
            ov[i++] = *++k;
        ov[i] = 0;
        ui.roll[c].sig = sig;
        if (!str_eq(ov, val))
            roll_note(c, ov, val, snap || named || vf != &AF_M || kid >= 0 || kind == LK_TALL || blocks);
        else if (snap)
            ui.roll[c].from[0] = 0;
        str_cpy(ui.col[c], key, sizeof ui.col[c]);
        if (kind == LK_TALL) {
            draw_column_tall(c, label, val, unit, vc, ratio, icon, hot, mot, kid, &sp);
            return;
        }
        if (blocks) {
            draw_column_blocks(c, label, val, unit, vc, ratio, icon, hot, mot, kid, kind);
            return;
        }
        cv_begin(COL_W, COL_H, T_BG);
        cv_rrect(0, 0, COL_W, COL_H, 4, T_SURF, T_BG);
    }
    if (label[0] || val[0]) {
        if (!strip && label[0]) {
            /* MENU > LARGE on a list / graph page or a layer (LK_LABEL): the label in M where it fits the card (its
             * capitals rows 5..15, the icon on them when it fits too), else in S as without LARGE */
            const aafont_t *lf = kind == LK_LABEL && 5 + text_w(&AF_M, label) <= COL_W - 2 ? &AF_M : &AF_S;
            int32_t lw = text_w(lf, label), ix = 5, ly = lf == &AF_M ? 1 : 3;
            int32_t cy = ly + (lf == &AF_M ? AF_M_CAP_Y : AF_S_CAP_Y), chh = lf == &AF_M ? AF_M_CAP_H : AF_S_CAP_H;
            uint32_t ic = mot ? ICON_X_MOTION : icon;
            if (mot && ix + ICON_CELL + ICON_GAP + lw > COL_W - 2)
                ix = COL_W - 2 - lw - ICON_GAP - ICON_CELL;   /* a long label: MOTION's icon moves left */
            if (FELUCCA_ICONS && ic != ICON_NONE && ix >= 1 && ix + ICON_CELL + ICON_GAP + lw <= COL_W - 2) {
                GFX_HOOK_ALIGN(ix, cy, ix, cy + chh, AL_V, "card icon on its label's line");
                lx = ix + cv_icon_in(ix, cy, 0, chh, ICON_CELL, ic,   /* its ink on the label's line */
                                     mot ? (hot ? T_ACCENT : T_THEME) : lc, T_SURF) + ICON_GAP;
            }
            else if (mot)                               /* the label from x 19 (5 + 12 + 2) */
                lc = hot ? T_ACCENT : T_THEME;          /* no room for MOTION's icon: the label says it */
            if (hot && T_ACCENT == T_MID) {             /* MONO: no colour tells the hot knob: its label inverted, */
                int32_t b[4], w;                        /* the chip 2 px round its ink (M: 3 above, 2 below) */
                text_ink(lf, label, b);
                w = b[2] - b[0] + 4;
                if (w > COL_W + 1 - lx - b[0]) w = COL_W + 1 - lx - b[0];
                cv_rrect(lx + b[0] - 2, cy - 3, w, lf == &AF_M ? chh + 5 : 15, 3, T_ACCENT, T_SURF);
                GFX_HOOK_ALIGN(lx + b[0] - 2, cy - 3, lx + b[0] - 2 + w, lf == &AF_M ? cy + chh + 2 : 18, AL_HV,
                               "card label chip (MONO hot)");
                cv_text_fit(lx, ly, lf, label, T_INK, T_ACCENT, COL_W - 2 - lx);
            } else
                cv_text_fit(lx, ly, lf, label, lc, T_SURF, COL_W - 2 - lx);
        }
        if (kid >= 0)                                   /* "[OCT+]": the keycap (accent: it would act; DIM: it would not) */
            x = cv_keycap(5, 20, (uint32_t)kid, vc == T_ACCENT || vc == T_DIM ? vc : T_KEY, T_INK, T_SURF);
        else if (vf == &AF_M) {
            if (!ui.roll[c].from[0] && val[0])
                GFX_HOOK_ALIGN(0, ROLL_Y, COL_W, ROLL_Y + ROLL_H, AL_V, "card value in its roll window");
            x = roll_text(c, 5, 17, val, vc);
        } else
            x = cv_text_fit(5, 20, vf, val, vc, T_SURF, room - uw);
        if (unit[0]) {
            GFX_HOOK_ALIGN(0, 0, 0, vf == &AF_M ? 17 + AF_M.asc : 20 + AF_S.asc, AL_B, "card unit on its value's baseline");
            cv_text_on(x + 3, 20, &AF_S, unit, T_MID, T_SURF);     /* on the value's baseline (S) */
        }
        if (!strip && ratio >= 0) {
            int32_t gw = COL_W - 10, fx = ratio * gw / 1000;
            cv_rrect(5, 38, gw, 3, 1, T_BG, T_SURF);
            cv_rrect(5, 38, fx < 3 ? 3 : fx, 3, 1, hot ? T_ACCENT : vc == T_DIM ? T_DIM : T_THEME, T_BG);
        }
    }
    cv_oy = 0;
    cv_blit((uint32_t)CARD_X(c), Y_LABEL + (strip ? ROLL_Y : 0));
}

static int preset_favorite(void)
{
    uint32_t k = user_of(TSEL);
    return favorite_has(k < UP_SLOTS ? NENGINES : TSEL->eng_req,
                                        k < UP_SLOTS ? k : TSEL->preset);
}

/* oscilloscope of the output, triggered on a rising zero crossing: a RAISE centre line, the trace 2 px (in silence
 * a flat line on it; MENU > SCREEN OFF keeps it from staying on the panel for hours) */
static void graph_scope(uint16_t c)
{
    static int16_t snap[SCOPE_N];
    uint32_t w = scope_w, i, trig = 0;
    int32_t cy = (int32_t)cv_h / 2, py = cy, x, peak = 1500, a = cv_h >= H_GRAPH ? 46 : cy - 6;   /* (LARGE: the strip) */
    if (ux.quark && cv_h >= H_GRAPH) {
        qk_detector(120, cy);
        return;
    }
    for (i = 0; i < SCOPE_N; i++) {
        snap[i] = scope_buf[(w + i) & (SCOPE_N - 1u)];
        if (snap[i] > peak)
            peak = snap[i];
        else if (-snap[i] > peak)
            peak = -snap[i];
    }
    for (i = 1; i < SCOPE_N - 240u; i++)
        if (snap[i - 1] < 0 && snap[i] >= 0) {
            trig = i;
            break;
        }
    if (ux.crypt) {                                  /* (Skiff N8) CRYPT: the sound burns: fire up from the foot as tall
                                                      * as the wave there (ember, amber, gold, its tips flame), flickering;
                                                      * behind it a skull, its eyes as bright as the sound is loud */
        int32_t foot = (int32_t)cv_h - 3, top = 6, k, loud = peak > 24000 ? 100 : peak * 100 / 24000;
        if (cv_h >= H_GRAPH)
            cr_spritez(120 - 13, 10, SPR_SKULL, ux_mix(T_DIM, T_SURF, 35),
                       loud < 50 ? ux_mix(T_SURF, CR_EMBER, loud * 2) : ux_mix(CR_EMBER, CR_FLAME, (loud - 50) * 2), 3);
        for (x = 0; x < PANEL_W; x += 2) {
            int32_t s = snap[trig + (uint32_t)x], v = (s < 0 ? -s : s) * (foot - top) / peak;
            v += (int32_t)((((uint32_t)x * 7u + ui.frame * 13u) >> 1) % 5u) - 2;   /* (the flicker) */
            if (v < 2)
                v = 2;
            for (k = 0; k < 4; k++) {                /* its four bands, the foot's first */
                int32_t y0 = foot - v * (k + 1) / 4, y1 = foot - v * k / 4;
                cv_rect(PANEL_X0 + x, y0, 2, y1 - y0, k == 0 ? CR_EMBER : k == 1 ? T_THEME : k == 2 ? CR_GOLD : CR_FLAME);
            }
        }
        return;
    }
    if (ux.neon && cv_h >= H_GRAPH) {                /* (Skiff N8) NEON: the sound as the skyline: the wave a ridge of
                                                      * vector mountains over the horizon, the striped sun behind it
                                                      * swelling with how loud it is, the floor running toward the viewer */
        int32_t hy = (int32_t)cv_h * 64 / 100, my = hy / 2 + 2, ma = hy / 2 - 6;
        ne_sun(120, hy, 14 + (peak > 24000 ? 24000 : peak) * 22 / 24000, 30);
        ne_grid_run(PANEL_X0, PANEL_X0 + PANEL_W, hy, (int32_t)cv_h - 2, T_THEME, T_SURF, (int32_t)(ui.frame * 125u % 1000u));
        cv_rect(PANEL_X0, hy, PANEL_W, 1, ux_mix(T_THEME, T_SURF, 30));
        for (x = 0; x < PANEL_W; x += 4) {
            int32_t y = my - snap[trig + (uint32_t)x] * ma / peak + 3;
            if (y < hy)
                cv_rect(PANEL_X0 + x, y, 1, hy - y, ux_mix(NE_VIOLET, T_SURF, 45));
        }
        cy = my;
        a = ma;
    } else
    cv_rect(PANEL_X0, cy, PANEL_W, 1, T_RAISE);
    for (x = 0; x < PANEL_W; x++) {
        int32_t y = cy - snap[trig + (uint32_t)x] * a / peak;    /* auto-scaled */
        if (x)
            cv_line_t(PANEL_X0 - 1 + x, py, PANEL_X0 + x, y, c, 2);
        py = y;
    }
}

/* a nucleus: its quarks (red, green, blue), two orbitals round it, an electron on one (gold) */
static void qk_nucleus(int32_t x, int32_t y, uint16_t c, int32_t r)
{
    qk_ellipse(x, y, r, r * 38 / 100, 0x15555555u, ux_mix(c, T_SURF, 30), 24);
    qk_ellipse(x, y, r, r * 38 / 100, 0xEAAAAAABu, ux_mix(c, T_SURF, 55), 24);
    cv_rect(x - 2, y - 2, 2, 2, T_TRK(0));
    cv_rect(x + 1, y - 2, 2, 2, T_TRK(1));
    cv_rect(x - 1, y + 1, 2, 2, T_TRK(2));
    cv_rect(x + r * 7 / 10, y - r * 3 / 10, 2, 2, T_ACCENT);
}

/* PATTERN page: the 64 steps as 4 rows of 16 bars (an accent: the accent colour, a tie: a lower bar,
 * empty: a stub), the cursor and the playhead under them */
static void graph_steps(const track_t *t, uint16_t c)
{
    uint32_t i, len = (uint32_t)t->p[P_SLEN];
    int32_t sm = graph_ht < 100;                     /* MENU > LARGE's strip: rows 14 px apart, bars 10 px */
    int32_t bh = sm ? 10 : 14, pitch = sm ? 14 : 24, y0 = sm ? 2 : 4;
    for (i = 0; i < NSTEP; i++) {
        int32_t x = bar_x(i), y = y0 + (int32_t)(i / 16u) * pitch;
        const step_t *st = &t->step[i];
        if (i >= len)
            continue;
        if (i % 16u == 0u && i + 16u <= len)
            GFX_HOOK_ALIGN(0, 0, 240, 0, AL_H | AL_CELLS | AL_N(16), "step bars' row centred");
        if (ux.crypt) {                              /* (Skiff S1) CRYPT: ASCII, # a note, - a tie, . nothing */
            int32_t base = y + bh / 2 + 4;
            if (step_on(st))
                cr_ch(x + 2, base, &AF_S, '#', (st->flags & SF_ACCENT) ? T_ACCENT : c);
            else if (step_tie(st))
                cr_ch(x + 3, base, &AF_S, '-', T_MID);
            else
                cr_ch(x + 4, base, &AF_S, '.', T_DIM);
        } else if (ux.quark) {                       /* (Skiff Q4) QUARK: a bunch, a tie its trail, nothing a dot */
            if (step_on(st))
                qk_disc(x + 4, y + bh / 2, bh > 10 ? 4 : 3, (st->flags & SF_ACCENT) ? T_ACCENT : c);
            else if (step_tie(st))
                cv_rect(x, y + bh / 2, 9, 1, T_MID);
            else
                cv_rect(x + 4, y + bh / 2, 1, 1, T_DIM);
        } else if (ux.neon && step_on(st))           /* (Skiff S1) NEON: a lit tube */
            ne_tube(x, y, 9, bh, (st->flags & SF_ACCENT) ? T_ACCENT : c, T_SURF);
        else if (step_on(st))
            cv_rrect(x, y, 9, bh, 2, (st->flags & SF_ACCENT) ? T_ACCENT : c, T_SURF);
        else if (step_tie(st))
            cv_rrect(x, y + bh - 6, 9, 6, 1, T_MID, T_SURF);
        else
            cv_rrect(x, y + bh - 3, 9, 3, 1, T_RAISE, T_SURF);
        if (i == ui.cursor && ux.neon)               /* ((Skiff S1) NEON: the cursor a laser, glowing) */
            cv_rect(x - 1, y + bh + 1 - sm, 11, 4, ux_mix(T_ACCENT, T_SURF, 60));
        if (i == ui.cursor)
            cv_rect(x, y + bh + 2 - sm, 9, 2, T_ACCENT);
        else if (song.playing && i == t->seq_idx)
            cv_rect(x, y + bh + 2 - sm, 9, 2, ux.crypt ? CR_GOLD : T_TEXT);
    }
    if (!sm) {                                       /* ((Skiff 2.0) the track's DIR, PRESETS': under the 100 px scale,
                                                      * right, as the roll's scale */
        char d[12] = "DIR ";
        str_cpy(d + 4, N_DIR[(uint32_t)t->p[P_DIR] % NELEM(N_DIR)], 8);
        cv_text_r(228, 102, &AF_S, d, T_MID, T_SURF);
    }
}

/* a bar w px wide in `hits` equal parts, 1 px apart (a RATCH step; 1: the bar) */
static void pr_split(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c, uint32_t hits)
{
    int32_t k, pw = (w - (int32_t)hits + 1) / (int32_t)hits;
    if (hits < 2u) {
        cv_rect(x, y, w, h, c);
        return;
    }
    for (k = 0; k < (int32_t)hits; k++)
        cv_rect(x + k * (pw + 1), y, pw, h, c);
}

static void list_row(int32_t y, int sel, const char *tag, uint16_t tc, const char *name, uint16_t nc, int32_t x1)
{
    uint16_t bg = sel ? T_THEME : T_SURF;
    if (sel)
        list_bar(y);
    GFX_HOOK_ALIGN(0, y, 0, y + 16, AL_V, "list row text centred up/down");
    cv_text_on(14, y + CAP_IN(S, 16), &AF_S, tag, sel ? T_INK : tc, bg);
    if (name[0])
        GFX_HOOK_ALIGN(0, y, 0, y + 16, AL_V, "list row text centred up/down");
    cv_free_text(54, y + CAP_IN(S, 16), &AF_S, name, sel ? T_INK : nc, bg, x1 - 54);
}

/* (Skiff 2.0) a column under a curve from (x, y) to the foot: NEON the sun's bands (from top), QUARK a Monte Carlo fill,
 * else fill */
static void pg_under(int32_t x, int32_t y, int32_t top, int32_t foot, uint16_t fill)
{
    if (ux.neon)
        ne_band_col(x, y, top, foot);
    else if (ux.quark)
        qk_mc(x, y, foot);
    else
        cv_rect(x, y, 1, foot - y, fill);
}

static void lcell(int32_t x, int32_t y, int32_t h, const char *note, uint32_t icon, const char *name, uint32_t st)
{
    uint16_t ink, fill = lc_fill(st, &ink), idle = fill == T_RAISE;
    int32_t in = lc_w < 40 ? 3 : 5;                        /* ((Skiff phase 9) FX's 30 px cells: the note and a REPEAT's
                                                            * division 3 px in, apart) */
    fill = lc_box(x, y, lc_w, h, fill);
    if (note)                                              /* (a 28 px cell, SEQ TOOLS: y + 1, Barlow's 10 px capitals */
        cv_text_on(x + in, y + (h > 24 && h <= 30 ? 1 : 3), &AF_S, note, idle ? T_MID : ink, fill);   /* clear its name) */
    if (h > 30) {
        GFX_HOOK_ALIGN(x, 0, x + lc_w, 0, AL_H, "FX cell icon centred across");
        cv_icon_on(x + (lc_w - 24) / 2, y + h - 25, 24, icon, ink, fill);   /* (its ink: rows 3 .. 20 of 24) */
        if (name)
            cv_text_r(x + lc_w - in, y + 3, &AF_S, name, ink, fill);
    } else if (h > 24) {                                   /* SEQ TOOLS: the icon (12 px) over the name, 2 px between, */
        int32_t b[4], t;                                   /* centred by ink (the icon at a side) */
        icon_ink(12, icon, b);
        t = y + HALF_UP(h - (14 + AF_S_CAP_H - b[1])) - b[1];
        GFX_HOOK_ALIGN(0, y, 0, y + h, AL_V | AL_N(2), "layer cell icon + name centred up/down");
        cv_icon_on(note ? x + lc_w - 17 : x + 5, t, 12, icon, ink, fill);
        GFX_HOOK_ALIGN(x, 0, x + lc_w, 0, AL_H | AL_PASS, "layer cell icon / name centred across");
        cv_text_in(x, t + 14 - AF_S_CAP_Y, lc_w, &AF_S, name, ink, fill);
    } else {                                               /* a key's row: the icon and the name on its middle */
        GFX_HOOK_ALIGN(0, y, 0, y + h, AL_V, "layer key cell icon / name centred up/down");
        cv_icon_in(x + 3, y, 0, h, 12, icon, ink, fill);
        GFX_HOOK_ALIGN(0, y, 0, y + h, AL_V, "layer key cell icon / name centred up/down");
        cv_text_r(x + lc_w - 3, y + CAP_IN(S, h), &AF_S, name, ink, fill);
    }
}

static void l6_mute(uint32_t k, uint32_t st, uint32_t icon)   /* (Skiff U2, R10) icon: GLO's MUTE (latched), FX's
                                                                * CUT while held: the gate, alone (as FX's white keys'
                                                                * effects: no room for it beside the note's name) */
{
    int32_t x = L6_X(k), y = LM_Y, b[4], cut = icon != ICON_MUTE;
    uint16_t ink, fill = lc_fill(st, &ink), idle = fill == T_RAISE;
    char n[3], d[2] = {(char)('1' + k), 0};
    bnote(n, k);
    fill = lc_box(x, y, L6_W, LM_H, fill);
    GFX_HOOK_ALIGN(0, y, 0, y + LM_H, AL_V, "layer key cell icon / name centred up/down");
    if (!cut)
        cv_text_on(x + 3, y + CAP_IN(S, LM_H), &AF_S, n, idle ? T_MID : ink, fill);
    /* the speaker's ink from x + 18 (its ink its lint box: no room for its empty margins), the gate's from x + 11;
     * the number in M (every style: no room for a cushion), the track's colour, its ink ending at x + 34 */
    icon_ink(12, icon, b);
    icon_lint_ink = 1;
    GFX_HOOK_ALIGN(0, y, 0, y + LM_H, AL_V, "layer key cell icon / name centred up/down");
    cv_icon_in(x + (cut ? 11 : 18) - b[0], y, 0, LM_H, 12, icon, ink, fill);
    icon_lint_ink = 0;
    text_ink(&AF_M, d, b);
    GFX_HOOK_ALIGN(0, y, 0, y + LM_H, AL_V, "layer key cell icon / name centred up/down");
    cv_text_on(x + 34 - b[2], y + CAP_IN(M, LM_H), &AF_M, d, idle ? T_TRK(k) : ink, fill);
}

/* 2^(i/192), Q16: pitch ratios in 1/16 semitones, d16 >= -3072 (16 octaves down) */
static uint32_t pow2_q16(int32_t d16)
{
    uint32_t u = (uint32_t)(d16 + 192 * 16), oct = u / 192u;     /* no loop for negative d16 */
    uint32_t r = pitch_inc(1600 + u % 192u) / (pitch_inc(1600) >> 16);   /* 2^(d/192) via the pitch table */
    return oct >= 16u ? r << (oct - 16u) : r >> (16u - oct);
}

static void sample_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const int16_t *p = t->p;
    const smp_zone_t *z = smp_zone((uint32_t)v->s[4]);
    uint32_t i, frac = v->ph[1];
    int32_t d16 = clamp(m->pitch16 + p[P_E1] * 16 - z->root16, -1536, 576);   /* <= 3 octaves up: bounded decode load */
    uint32_t r = pow2_q16(d16), stepq = (r >> 8) * (z->rate >> 8);   /* Q16 samples per output */
    int32_t bits = p[P_E2], lp = 4000 + ((clamp((p[P_E4] << 8) + m->cutoff, 0, 127 << 8) * 28767) >> 15);
    int32_t drv = p[P_E6], sh = bits / 10;
    if (v->s[6] == 2) {                               /* no sample data: the sine at the note's pitch + TUNE */
        smp_sine(out, n, m, p[P_E1] * 16, lp, &v->ph[0], &v->s[7]);
        return;
    }
    if (v->s[6] || !z->n) {
        v->active = 0;
        return;
    }
    if (v->ph[0] == 0 && v->ph[1] == 0 && v->s[3] == 0)
        v->s[3] = sample_next(z, v, p[P_E3]);         /* prime the interpolator */
    for (i = 0; i < n; i++) {
        int32_t s;
        frac += stepq;
        while (frac >= 65536u) {
            frac -= 65536u;
            v->s[2] = v->s[3];
            if (v->ph[0] >= z->n) {                   /* one-shot reached its end */
                v->s[6] = 1;
                v->s[3] = 0;
                if (frac >= 65536u) {                /* past the last sample-to-zero interval */
                    v->s[2] = 0;
                    frac &= 65535u;
                }
                break;
            }
            v->s[3] = sample_next(z, v, p[P_E3]);
        }
        s = v->s[2] + (((v->s[3] - v->s[2]) * (int32_t)(frac >> 1)) >> 15);
        if (sh)                                       /* BITS: 0 = clean, up to 12 bits removed */
            s = (s >> sh) << sh;
        if (drv)
            s = softclip(s + (((s >> 2) * (drv * 150)) >> 11));   /* = s * drv * 600 / 32768, no overflow */
        v->s[7] += mulq15(s - v->s[7], lp);           /* gentle tone control (CUT) */
        out[i] += voice_amp(v->s[7], m, i) << 1;
        if (v->s[6])
            break;
    }
    v->ph[1] = frac;
    if (v->s[5])
        sample_declick(v, out, n, m);
}

static inline int slc_rev(const slc_src_t *s, voice_t *v, int16_t *rb, int loop, int32_t *x)
{
    uint32_t q = v->ph[0], ws = (uint32_t)v->s[0], a, b, st;
    if (q <= v->ph[2]) {
        if (!loop)
            return 0;
        slc_bounds_v(s, v, &a, &b, &st);
        q = b;
        v->ph[2] = a;                                   /* (MAN: a JOIN / move meanwhile changed the start too) */
    }
    q--;
    if (q < ws || q >= ws + SLC_RB) {
        slc_bounds_v(s, v, &a, &b, &st);
        if (q < a)                                      /* MAN: the start moved past this voice: it ends */
            return 0;
        ws = q + 1u >= a + SLC_RB ? q + 1u - SLC_RB : a;
        slc_fill(s, rb, ws, q + 1u - ws, a, st);
        v->s[0] = (int32_t)ws;
    }
    *x = rb[q - ws];
    v->ph[0] = q;
    return 1;
}

/* the four cards: the window's */
static void fm_cards_of(uint32_t pg)
{
    const uint8_t *p = fm6_patch[fm_tr()];
    uint32_t w = fm_ui[1 + pg] % FM_NWIN, k;
    for (k = 0; k < 4u; k++) {
        const fm_field_t *f = &FM_F[pg & 1u][w][k];
        char val[12];
        const char *unit;
        int32_t g;
        if (!f->label) {
            draw_column(k, "", "", "", VR_THEME, -1, ICON_NONE);
            continue;
        }
        g = fm_val(f, fm_at(pg, f), p, TSEL, val, &unit);
        draw_column(k, f->label, val, unit, VR_LIVE, g, ICON_NONE);
    }
}

/* the loudest sounding carrier's level at column x */
static int32_t fm_loud(const fm_sim_t *s, int32_t x)
{
    int32_t lv = 0, v;
    uint32_t k;
    for (k = 0; k < 6u; k++)
        if ((s->car & s->live) >> k & 1u && (v = fm_at_x(&s->op[k], x)) > lv)
            lv = v;
    return lv;
}
